"""Generate or check the documented catalog against executable metadata."""
from pathlib import Path
import argparse, sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'source'))
from feature_hub import FEATURES

def render():
    lines=['# Implemented Feature Studio catalog','','Exactly **100 actions**: 30 diagnostics, 35 report analyses, 25 planning/export actions (including ten profiles), and ten dashboard controls. These are implemented operations, presets and preferences, not 100 software installers.','','IDs below use the `studio:` namespace. The separate proposal snapshot uses `roadmap:Fnnn`; see [status reconciliation](ROADMAP-STATUS.md).','','Profiles change optional selections only after explicit Apply; core components remain included. No studio analysis makes a model request. Simulation skips native diagnostic commands and network checks. Reports and downloads remain local.','','| ID | Action | Effect | Requirement |','| --- | --- | --- | --- |']
    for feature in FEATURES:
        number=int(feature['id'][1:])
        requirement='Local Windows environment; missing evidence is reported' if number<=30 else 'Completed diagnostic; comparisons need a preceding run' if number<=65 or 81<=number<=86 else 'Dashboard session'
        if number in (23,24,25):requirement='Internet access to the named official catalog'
        if number in (87,89):requirement='Installation idle; validated Workbench-owned recipe path'
        if number==88:requirement='A saved local selection recipe'
        lines.append('| '+' | '.join(str(x).replace('|','\\|') for x in ('studio:'+feature['id'],feature['title'],feature['effect'],requirement))+' |')
    lines.extend(['','## Catalog contract','','Every ID maps to one registered handler or one active browser control. Server jobs admit at most two concurrent actions. The code and offline fixture tests establish callable behavior; they do not certify every laptop, account, desktop UI or external publisher. [Verification](../source/VERIFICATION.md) records those evidence classes separately.','','Generated by `python tools/feature_catalog.py`; check with `--check`.'])
    return '\n'.join(lines)+'\n'

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    path=ROOT/'docs/FEATURE-CATALOG.md';content=render()
    if args.check:
        if not path.is_file() or path.read_text(encoding='utf-8')!=content:raise SystemExit('Documented feature catalog differs from executable metadata.')
        print('All 100 documented actions match executable metadata.')
    else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding='utf-8',newline='\n');print('Generated 100-action catalog.')
